export async function main(user_id: number) {
  const todos: { title: string; completed: boolean }[] = await (
    await fetch(`https://jsonplaceholder.typicode.com/todos?userId=${user_id}`)
  ).json()
  const open = todos.filter((t) => !t.completed)
  return { user_id, open: open.length, titles: open.map((t) => t.title) }
}
